(() => {
  'use strict';
  // P-paper (2026-10-28): the app picks one paper worksheet, the child solves it with a pencil,
  // and a grown-up taps only the wrong numbers. Results go into the same game records as play
  // (stats, today's count, the 🔁 missed list S.review and the 1·3·7-day window.Spacing).
  // Questions are generated by the games themselves without rendering: quiz()/tileRound() are
  // swapped for a moment (same idea as adaptive-extra.js), so the paper uses the game banks as they are.
  // Device-only: the last 3 sheets (question data, no child name) live in localStorage 'sag.paper.<child>'.
  // Nothing is uploaded. The printable page is a sandboxed iframe with no scripts (same as print.js).
  const MAX_SHEETS = 3, MAX_HTML = 24000, MAX_SHEET_BYTES = 400000;
  const STORE = () => 'sag.paper.' + (typeof PROF !== 'undefined' && PROF.active ? PROF.active : 'p1');
  const cssURL = new URL('paper.css', document.currentScript ? document.currentScript.src : document.baseURI).href;
  const baseURL = new URL('./', document.currentScript ? document.currentScript.src : document.baseURI).href;
  const esc = v => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const plain = html => String(html || '').replace(/<(script|style|button)\b[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
  // Static, printable HTML only: no buttons (read-aloud), scripts, inputs, handlers or canvas.
  const tidy = html => String(html || '')
    .replace(/<(script|style|button|template|iframe|object|embed)\b[\s\S]*?<\/\1>/gi, '')
    .replace(/<(input|textarea|select)\b[^>]*>/gi, '')
    .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, '')
    .replace(/(href|src)\s*=\s*("|')\s*javascript:[^"']*\2/gi, '');
  const LETTERS = ['A', 'B', 'C', 'D', 'E', 'F'];
  const tr = (en, ko) => L(B(en, ko));
  const gradeName = g => g === 'K' ? tr('Kindergarten', '유치원') : tr(`Grade ${g}`, `${g}학년`);
  const dateKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

  // ---- storage (per child, newest first, at most 3) ----
  const okSheet = s => s && typeof s === 'object' && typeof s.id === 'string' && /^[a-z0-9_]{4,40}$/.test(s.id) && Array.isArray(s.items) && s.items.length >= 1 && s.items.length <= 12
    && s.items.every(it => it && typeof it.g === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(it.g) && ['q', 'h'].includes(it.kind) && Number.isInteger(it.lv) && it.lv >= 1 && it.lv <= 3);
  const load = () => {
    try { const raw = JSON.parse(localStorage.getItem(STORE()) || '[]'); return (Array.isArray(raw) ? raw : []).filter(okSheet).slice(0, MAX_SHEETS); }
    catch (e) { return []; }
  };
  let memory = null;   // used when storage is full or blocked: the sheet still prints and grades this visit
  const sheets = () => memory || load();
  const store = list => {
    list = list.slice(0, MAX_SHEETS);
    try { localStorage.setItem(STORE(), JSON.stringify(list)); memory = null; return true; }
    catch (e) { memory = list; return false; }
  };

  // ---- question capture (no rendering) ----
  const capable = (g, grade) => {
    if (!g || g.grade === 'P' || heldGame(g) || (typeof CHECK_SKIP !== 'undefined' && CHECK_SKIP.includes(g.id))) return false;
    const gr = gradeOf(g);
    return gr === grade || (S.showK && gr === prevGrade(grade));
  };
  // A question that only works by sound, by dragging or with live drawing cannot go on paper.
  const printable = item => {
    if (!item || !Array.isArray(item.opts) || item.opts.length < 2 || item.opts.length > 6) return false;
    if (item.opts.filter(o => o && o.ok).length !== 1) return false;
    const all = (item.show || '') + item.opts.map(o => (o && o.html) || '').join('');
    if (/<(canvas|video|audio|input|textarea|select)\b/i.test(all)) return false;
    const ask = plain(L(item.ask || ''));
    if (!ask) return false;
    if (/\blisten\b|\bhear\b|듣고|들어/i.test(ask) && !plain(item.show || '')) return false;   // sound-only round
    return all.length <= MAX_HTML;
  };
  function capture(game) {
    const real = { quiz: window.quiz, tile: window.tileRound };
    const keep = { review: SESSION.review, easy: SESSION.easyLevel, diag: DIAG.active };
    let got = null;
    try {
      SESSION.review = null; SESSION.easyLevel = false; DIAG.active = false;
      window.quiz = (_g, item) => { if (!got) got = { item }; };
      window.tileRound = () => { got = got || { tile: true }; };
      game.play.call(game);
    } catch (e) { got = null; }
    finally { window.quiz = real.quiz; window.tileRound = real.tile; SESSION.review = keep.review; SESSION.easyLevel = keep.easy; DIAG.active = keep.diag; }
    return got && !got.tile && printable(got.item) ? got.item : null;
  }
  // Screen verbs become pencil verbs ("Tap each one" -> "Point to each one").
  const paperWords = text => text.replace(/\bTap\b/g, 'Point to').replace(/\btap\b/g, 'point to').replace(/눌러서/g, '손가락으로 짚으며').replace(/눌러 보세요|눌러요/g, '짚어 봐요');
  const toItem = (game, item) => {
    const opts = shuffle(item.opts);
    const html = o => tidy(o.html) + (o.label ? `<span class="pw-ol">${tidy(labelText(o.label))}</span>` : '');
    const ans = opts.findIndex(o => o.ok), right = opts[ans];
    const words = plain(right.html) || (right.label ? plain(labelText(right.label)) : '');
    return { g: game.id, lv: lvl(game.id), kind: 'q', ask: paperWords(plain(L(item.ask))), show: tidy(item.show || ''), opts: opts.map(html), ans, key: LETTERS[ans] + (words && words.length <= 40 ? ' · ' + words : '') };
  };

  // ---- kindergarten hand activities (empty box, pencil) ----
  const handTasks = () => {
    const k = id => { const g = gameById(id); return g && gradeOf(g) === 'K' && !heldGame(g) ? id : null; };
    const shapes = [[B('triangle', '세모'), B('3 sides, 3 corners', '변 3개, 꼭짓점 3개')], [B('square', '네모(정사각형)'), B('4 equal sides', '같은 길이의 변 4개')], [B('circle', '동그라미'), B('round, no corners', '둥글고 꼭짓점 없음')], [B('rectangle', '직사각형'), B('4 sides, 2 long + 2 short', '긴 변 2개, 짧은 변 2개')]];
    const letters = 'ABDEFGHMNRST';
    return [
      () => { const n = 3 + rnd(7); return k('count') && { g: 'count', box: 'draw', ask: tr(`Draw ${n} circles.`, `동그라미 ${n}개를 그려 보세요.`), hint: `<span class="pw-big">${n}</span> <span aria-hidden="true">○</span>`, key: tr(`${n} circles`, `동그라미 ${n}개`) }; },
      () => { const n = 2 + rnd(15); return k('order') && { g: 'order', box: 'write', ask: tr('Write the number that comes next.', '다음에 오는 수를 써 보세요.'), hint: `<span class="pw-seq">${n - 2} &nbsp; ${n - 1} &nbsp; ${n} &nbsp; <span class="pw-blank"></span></span>`, key: String(n + 1) }; },
      () => { const s = pick(shapes); return k('shapes2d') && { g: 'shapes2d', box: 'draw', ask: tr(`Draw a ${s[0].en}.`, `${s[0].ko}를 그려 보세요.`), hint: '', key: L(s[0]) + ' · ' + L(s[1]) }; },
      () => { const c = letters[rnd(letters.length)]; return k('letters') && { g: 'letters', box: 'write', ask: tr(`Trace, then write ${c} and ${c.toLowerCase()}.`, `${c}와 ${c.toLowerCase()}를 따라 쓰고 한 번 더 써 보세요.`), hint: `<span class="pw-trace">${c} ${c.toLowerCase()}</span>`, key: `${c} ${c.toLowerCase()}` }; }
    ];
  };

  // ---- which games: Peachy's picks, then weak areas, then least-accurate tried games, then the grade's core games ----
  function chooseGames(grade) {
    const ok = id => capable(gameById(id), grade);
    const out = [], why = {}, add = (id, w) => { if (ok(id) && !out.includes(id)) { out.push(id); why[id] = w; } };
    try { currentPicks(6).forEach(p => add(p.id, 'pick')); } catch (e) {}
    try {
      const L2 = window.Learner;
      if (L2 && L2.domainList) L2.domainList().filter(d => !d.reviewOnly && L2.weakDomain(d)).forEach(d => shuffle(d.g[grade] || []).forEach(id => add(id, 'weak')));
    } catch (e) {}
    GAMES.filter(g => capable(g, grade)).map(g => ({ id: g.id, s: S.stats[g.id] || freshStat() })).filter(x => x.s.right + x.s.wrong >= 3)
      .sort((a, b) => a.s.right / (a.s.right + a.s.wrong) - b.s.right / (b.s.right + b.s.wrong)).forEach(x => add(x.id, 'low'));
    const core = typeof ADAPT_DOMAINS !== 'undefined' ? ['math', 'read'].flatMap(s => (ADAPT_DOMAINS[s] || []).flatMap(d => d.g[grade] || [])) : [];
    shuffle(core).forEach(id => add(id, 'core'));
    return { ids: out, why };
  }
  function makeSheet() {
    const grade = kidGrade();
    if (grade === 'P') return null;
    const target = grade === 'K' ? 4 : ['1', '2'].includes(grade) ? 8 : 6, hands = grade === 'K' ? 2 : 0;   // K 4+2 hand boxes, 1-2: 8, 3-5: 6 (longer text, keeps one page readable)
    const { ids, why } = chooseGames(grade);
    const items = [], seen = new Set(), used = [];
    try { window.LearnLog.finish(); } catch (e) {}
    // Up to 4 games, about target/4 questions each; a game that cannot be captured is skipped.
    for (const id of ids) {
      if (used.length >= 4 && items.length >= target) break;
      if (used.length >= 4) break;
      const game = gameById(id), per = Math.ceil(target / 4);
      let got = 0;
      for (let attempt = 0; attempt < 12 && got < per; attempt++) {
        const item = capture(game); if (!item) break;
        const key = plain(L(item.ask)) + '|' + plain(item.show) + '|' + item.opts.filter(o => o.ok).map(o => o.html).join('');
        if (seen.has(key)) continue;
        seen.add(key); items.push({ ...toItem(game, item), why: why[id] }); got++;
      }
      if (got) used.push(id);
    }
    // Top up from the chosen games when a game had too few distinct questions.
    for (let pass = 0; pass < 8 && items.length < target && used.length; pass++) {
      const game = gameById(used[pass % used.length]), item = capture(game);
      if (!item) continue;
      const key = plain(L(item.ask)) + '|' + plain(item.show) + '|' + item.opts.filter(o => o.ok).map(o => o.html).join('');
      if (!seen.has(key)) { seen.add(key); items.push({ ...toItem(game, item), why: why[game.id] }); }
    }
    if (hands) {
      const tasks = handTasks(), weakIds = new Set(ids.slice(0, 8));
      const order = shuffle(tasks.map((f, i) => i)).sort((a, b) => (weakIds.has(['count', 'order', 'shapes2d', 'letters'][b]) ? 1 : 0) - (weakIds.has(['count', 'order', 'shapes2d', 'letters'][a]) ? 1 : 0));
      let n = 0;
      for (const i of order) { if (n >= hands) break; const t = tasks[i](); if (t) { items.push({ kind: 'h', lv: lvl(t.g), ...t }); n++; } }
    }
    try { window.LearnLog.finish(); if (typeof NEXT_TOK !== 'undefined') NEXT_TOK++; if ('speechSynthesis' in window) speechSynthesis.cancel(); } catch (e) {}
    if (!items.length) return null;
    // Questions first, hand activities last; numbered 1..n.
    const qs = items.filter(i => i.kind === 'q').slice(0, target), hs = items.filter(i => i.kind === 'h');
    const all = qs.concat(hs);
    const areas = [...new Set(all.map(it => { const d = window.Learner && window.Learner.domainFor && window.Learner.domainFor(it.g); return d ? L(d.n) : ''; }).filter(Boolean))].slice(0, 3);
    const sheet = { id: 'pw' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), at: new Date().toISOString(), date: dateKey(), grade, lang: S.lang, areas, items: all, graded: null };
    while (JSON.stringify(sheet).length > MAX_SHEET_BYTES && sheet.items.length > 4) sheet.items.splice(sheet.items.findIndex(i => i.kind === 'q'), 1);
    return sheet;
  }

  // ---- printable HTML (one page; answer key below a cut line or on page 2) ----
  function sheetHtml(sheet, keyOnPage2) {
    const ko = sheet.lang === 'ko', t = (en, kr) => ko ? kr : en;
    const gname = sheet.grade === 'K' ? t('Kindergarten', '유치원') : t(`Grade ${sheet.grade}`, `${sheet.grade}학년`);
    const k = sheet.grade === 'K' || sheet.grade === '1';
    const q = (it, n) => it.kind === 'h'
      ? `<li class="pw-q pw-hand"><div class="pw-ask"><b class="pw-n">${n}</b> ${esc(it.ask)}</div>${it.hint ? `<div class="pw-hint">${it.hint}</div>` : ''}<div class="pw-box ${it.box === 'write' ? 'pw-lines' : ''}" aria-label="${esc(t('Space to draw or write', '그리거나 쓰는 칸'))}"></div></li>`
      : `<li class="pw-q"><div class="pw-ask"><b class="pw-n">${n}</b> ${esc(it.ask)}</div>${it.show ? `<div class="pw-show">${it.show}</div>` : ''}<ol class="pw-opts">${it.opts.map((o, i) => `<li><span class="pw-letter">${LETTERS[i]}</span><span class="pw-o">${o}</span></li>`).join('')}</ol></li>`;
    const keyRows = sheet.items.map((it, i) => `<li><b>${i + 1}.</b> ${esc(it.key)}</li>`).join('');
    const key = `<section class="pw-key${keyOnPage2 ? ' pw-page2' : ''}">${keyOnPage2 ? '' : `<div class="pw-cut">✂ ${esc(t('Grown-ups: cut here and keep the answers', '보호자용: 여기를 잘라 정답을 따로 두세요'))} ✂</div>`}<h2>${esc(t('Answers (grown-ups)', '정답 (보호자용)'))} · ${esc(sheet.date)}</h2><ol class="pw-keylist">${keyRows}</ol><p class="pw-small">${esc(t('In PeachPlay: Grown-ups → Paper worksheet → Grade, then tap only the numbers that were wrong.', 'PeachPlay 보호자 화면 → 종이 학습지 → 채점하기에서 틀린 번호만 누르세요.'))}</p></section>`;
    const head = `<header class="pw-head"><div class="pw-title">🍑 ${esc(t('PeachPlay practice sheet', 'PeachPlay 연습 학습지'))}</div><div class="pw-fill"><span>${esc(t('Name', '이름'))} <i></i></span><span>${esc(t('Date', '날짜'))} <i></i></span></div><div class="pw-sub">${esc(gname)}${sheet.areas.length ? ' · ' + esc(sheet.areas.join(' · ')) : ''}</div><div class="pw-how">${esc(k ? t('A grown-up reads each question aloud. Circle the answer. Draw or write in the boxes.', '보호자가 문제를 읽어 주세요. 답에 동그라미 하고, 빈 상자에는 그리거나 써요.') : t('Circle the letter of the best answer.', '가장 알맞은 답의 글자에 동그라미 하세요.'))}</div></header>`;
    return `<!doctype html><html lang="${ko ? 'ko' : 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="${esc(baseURL)}"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'none'"><title>PeachPlay</title><link rel="stylesheet" href="${esc(cssURL)}"><style>@page{size:auto;margin:9mm}</style></head><body class="pw-doc${sheet.grade === 'K' ? ' pw-k' : ''}"><main class="pw-sheet">${head}<ol class="pw-list">${sheet.items.map((it, i) => q(it, i + 1)).join('')}</ol>${key}</main></body></html>`;
  }
  // One page: the sheet is laid out at the printable width (192mm) and zoomed down when it is taller than
  // the shorter printable height (Letter 279mm - 2 x 9mm margins = 261mm; 255mm keeps a safety gap).
  // Below 62% the print would be too small for young children, so it is left to flow onto a 2nd page.
  const PAGE_MM = 255, MIN_SCALE = 0.62;
  function fitOnePage(doc, keyOnPage2) {
    try {
      const sheet = doc.querySelector('.pw-sheet'); if (!sheet) return 1;
      sheet.style.zoom = '';
      const px = mm => mm * 96 / 25.4, top = sheet.getBoundingClientRect().top;
      const key = doc.querySelector('.pw-key');
      const bottom = keyOnPage2 && key ? doc.querySelector('.pw-list').getBoundingClientRect().bottom : sheet.getBoundingClientRect().bottom;
      const h = bottom - top, scale = h > px(PAGE_MM) ? Math.max(MIN_SCALE, Math.floor(px(PAGE_MM) / h * 100) / 100) : 1;
      if (scale < 1) sheet.style.zoom = String(scale);
      sheet.dataset.scale = String(scale); sheet.dataset.mm = String(Math.round(h * 25.4 / 96));
      return scale;
    } catch (e) { return 1; }
  }
  function printSheet(sheet, keyOnPage2) {
    document.querySelector('.p-dialog')?.remove();
    const dialog = document.createElement('dialog'); dialog.className = 'p-dialog pw-dialog';
    const bar = document.createElement('div'); bar.className = 'p-toolbar';
    const go = document.createElement('button'); go.textContent = tr('Print / Save PDF', '인쇄 / PDF 저장'); go.disabled = true; go.id = 'pwGo';
    const close = document.createElement('button'); close.textContent = tr('Close', '닫기'); close.onclick = () => dialog.close();
    const status = document.createElement('span'); status.setAttribute('role', 'status'); status.textContent = tr('Loading print preview…', '인쇄 미리보기를 불러와요…');
    bar.append(go, close, status);
    const frame = document.createElement('iframe'); frame.className = 'p-frame pw-frame'; frame.title = tr('Paper worksheet', '종이 학습지');
    frame.setAttribute('sandbox', 'allow-same-origin allow-modals');
    frame.srcdoc = sheetHtml(sheet, keyOnPage2);
    frame.onload = () => {
      const ready = !!(frame.contentDocument && frame.contentDocument.styleSheets.length);
      const scale = ready ? fitOnePage(frame.contentDocument, keyOnPage2) : 1;
      go.disabled = !ready;
      status.textContent = ready ? tr('Ready. Letter or A4, black and white is fine.', '준비됐어요. Letter/A4, 흑백 인쇄로 충분해요.') + (scale < 1 ? ' ' + tr(`(shrunk to ${Math.round(scale * 100)}% to fit one page)`, `(한 장에 맞게 ${Math.round(scale * 100)}%로 줄였어요)`) : '') : tr('Print styles could not load. Close and try again.', '인쇄 스타일을 불러오지 못했어요. 닫고 다시 시도해 주세요.');
    };
    go.onclick = () => { frame.contentWindow.focus(); frame.contentWindow.print(); };
    dialog.addEventListener('close', () => dialog.remove(), { once: true });
    dialog.append(bar, frame); document.body.append(dialog); dialog.showModal(); close.focus();
    return frame;
  }

  // ---- grading: same records as play ----
  function recordItem(id, ok, lv) {
    if (!gameById(id)) return false;
    if (typeof window.recordPaper === 'function') { window.recordPaper(id, ok, lv); return true; }   // optional core hook (docs/review/integ-paper.md)
    const keep = { id: SESSION.id, review: SESSION.review, easy: SESSION.easyLevel, diag: DIAG.active };
    try {
      window.LearnLog.finish();                       // no timing row: paper has no response time (see integ doc)
      SESSION.id = null; SESSION.review = null; SESSION.easyLevel = false; DIAG.active = false;
      MISS[id] = false; record(id, ok); MISS[id] = false;
      return true;
    } finally { SESSION.id = keep.id; SESSION.review = keep.review; SESSION.easyLevel = keep.easy; DIAG.active = keep.diag; }
  }
  function applyGrade(sheetId, wrong) {
    const list = sheets(), sheet = list.find(s => s.id === sheetId);
    if (!sheet || sheet.graded || kidGrade() === 'P') return null;
    const bad = new Set(wrong);
    sheet.items.forEach((it, i) => recordItem(it.g, !bad.has(i), it.lv));
    sheet.graded = { at: new Date().toISOString(), wrong: [...bad].filter(i => Number.isInteger(i) && i >= 0 && i < sheet.items.length).sort((a, b) => a - b) };
    save(); store(list);
    return sheet;
  }

  // ---- grown-ups screens ----
  let back = null, key2Pref = false;
  const title = it => { const g = gameById(it.g); return g ? `${g.icon} ${L(g.title)}` : it.g; };
  function screen(msg) {
    if (kidGrade() === 'P') return back ? back() : home();
    const list = sheets();
    const rows = list.map(s => `<li class="pw-row"><div><b>${esc(s.date)}</b> · ${s.items.length}${esc(tr(' questions', '문항'))} · ${s.graded ? `✅ ${esc(tr(`${s.items.length - s.graded.wrong.length}/${s.items.length} right`, `${s.items.length - s.graded.wrong.length}/${s.items.length} 맞음`))}` : `✏️ ${esc(tr('not graded yet', '아직 채점 전'))}`}${s.grade !== kidGrade() ? ` · ${esc(gradeName(s.grade))}` : ''}</div>
      <div class="pw-acts"><button class="pill" data-pwprint="${s.id}">🖨️ ${esc(tr('Print again', '다시 인쇄'))}</button>${s.graded ? '' : `<button class="pill" data-pwgrade="${s.id}">✔️ ${esc(tr('Grade', '채점하기'))}</button>`}</div></li>`).join('');
    view().innerHTML = `<h1>📝 ${esc(tr('Paper worksheet', '종이 학습지'))}</h1>
      <p class="note2">${esc(tr('Peachy picks questions from weaker areas. Your child solves them on paper with a pencil; you tap only the wrong numbers. Results join the game records and the review lists. Nothing is sent; the child\'s name is written by hand and never saved.', '피치가 약한 영역에서 문제를 골라요. 아이는 종이에 연필로 풀고, 보호자는 틀린 번호만 눌러요. 결과는 게임 기록과 다시 도전·간격 복습에 들어가요. 아무것도 전송하지 않고, 이름은 손으로 쓰며 저장하지 않아요.'))}</p>
      ${msg ? `<p class="pw-msg" role="status">${esc(msg)}</p>` : ''}
      <div class="pw-make"><button class="next" id="pwMake">📝 ${esc(tr('Make a paper worksheet', '종이 학습지 만들기'))}</button>
      <label class="pw-chk"><input type="checkbox" id="pwKey2"${key2Pref ? ' checked' : ''}> ${esc(tr('Answers on a separate page 2', '정답은 2쪽에 따로'))}</label></div>
      <h2>${esc(tr('Recent sheets (this device, last 3)', '최근 학습지 (이 기기, 3장까지)'))}</h2>
      ${rows ? `<ul class="pw-rows">${rows}</ul>` : `<p class="note2">${esc(tr('No sheets yet.', '아직 만든 학습지가 없어요.'))}</p>`}
      ${memory ? `<p class="note2">${esc(tr('This device could not save the sheet list; it stays until you close the app.', '이 기기에 학습지 목록을 저장하지 못했어요. 앱을 닫기 전까지만 남아 있어요.'))}</p>` : ''}
      <div><button class="next" id="b">${T().back}</button></div>`;
    const key2 = () => !!($('#pwKey2') && $('#pwKey2').checked);
    $('#pwKey2').onchange = () => { key2Pref = key2(); };
    $('#pwMake').onclick = () => {
      const sheet = makeSheet();
      if (!sheet) return screen(tr('Could not make a sheet for this grade yet.', '이 학년은 아직 학습지를 만들 수 없어요.'));
      const saved = store([sheet].concat(sheets().filter(s => s.id !== sheet.id)));
      screen(saved ? '' : tr('Saved for this visit only (device storage is full or blocked).', '이번 방문에만 보관돼요(기기 저장 공간이 가득 찼거나 막혀 있어요).'));
      printSheet(sheet, key2());
    };
    $$('[data-pwprint]').forEach(b => b.onclick = () => { const s = sheets().find(x => x.id === b.dataset.pwprint); if (s) printSheet(s, key2()); });
    $$('[data-pwgrade]').forEach(b => b.onclick = () => gradeScreen(b.dataset.pwgrade));
    $('#b').onclick = () => (back ? back() : home());
    window.scrollTo(0, 0);
  }
  function gradeScreen(sheetId) {
    const sheet = sheets().find(s => s.id === sheetId);
    if (!sheet || sheet.graded) return screen();
    const wrong = new Set();
    view().innerHTML = `<h1>✔️ ${esc(tr('Grade the sheet', '학습지 채점하기'))}</h1>
      <p class="note2">${esc(tr(`Sheet of ${sheet.date}. Tap only the numbers your child got wrong (or left blank), then save. Check the answers on the cut-off strip or page 2.`, `${sheet.date} 학습지예요. 틀렸거나 비워 둔 번호만 누르고 저장하세요. 정답은 잘라 둔 줄이나 2쪽에 있어요.`))}</p>
      <div class="pw-grid">${sheet.items.map((it, i) => `<button class="pw-num" data-pwn="${i}" aria-pressed="false"><b>${i + 1}</b><small>${esc(title(it))}</small></button>`).join('')}</div>
      <p class="pw-msg" id="pwCount" role="status"></p>
      <div><button class="next" id="pwSave">💾 ${esc(tr('Save results', '결과 저장'))}</button> <button class="pill" id="pwCancel">${esc(tr('Cancel', '취소'))}</button></div>`;
    const count = () => { $('#pwCount').textContent = tr(`Wrong: ${wrong.size} · Right: ${sheet.items.length - wrong.size}`, `틀림 ${wrong.size}개 · 맞음 ${sheet.items.length - wrong.size}개`); };
    $$('.pw-num').forEach(b => b.onclick = () => {
      const i = +b.dataset.pwn; if (wrong.has(i)) wrong.delete(i); else wrong.add(i);
      b.classList.toggle('wrong', wrong.has(i)); b.setAttribute('aria-pressed', String(wrong.has(i)));
    });
    count(); $$('.pw-num').forEach(b => b.addEventListener('click', count));
    $('#pwCancel').onclick = () => screen();
    $('#pwSave').onclick = () => {
      const done = applyGrade(sheet.id, [...wrong]);
      if (!done) return screen();
      const right = done.items.length - done.graded.wrong.length;
      screen(tr(`Saved: ${right}/${done.items.length} right. ${done.graded.wrong.length ? 'Missed questions were added to Try again and spaced review.' : 'Great work!'}`, `저장했어요: ${done.items.length}문항 중 ${right}개 맞음. ${done.graded.wrong.length ? '틀린 문항은 다시 도전·간격 복습에 넣었어요.' : '잘했어요!'}`));
    };
    window.scrollTo(0, 0);
  }
  window.Paper = { open(onBack) { back = typeof onBack === 'function' ? onBack : null; screen(); }, make: makeSheet, html: sheetHtml, print: printSheet, grade: applyGrade, list: sheets, clear() { memory = null; try { localStorage.removeItem(STORE()); } catch (e) {} } };
})();
